import rawGeometry from '../assets/mushafGeometry.json';

// Per-page tap-targeting data generated by scripts/generate-mushaf-geometry.mjs.
type PageGeometry = {
  /** SVG viewBox [width, height]. */
  vb: [number, number];
  /** y-centre of each text line. */
  lines: number[];
  /** [minX, maxX] of the text block. */
  x: [number, number];
  /** End-of-ayah markers as [lineIndex, x], in reading order. */
  markers: [number, number][];
};

const geometry = rawGeometry as unknown as Record<string, PageGeometry>;

export const TOTAL_AYAHS = 6236;

// First marker (== ayah) index of every page: markers appear in the SVGs in Quran
// order, so the Nth marker in the whole mushaf is the Nth ayah (verified against
// every surah's ayah count when the geometry is generated).
const pageStartIndex: number[] = [0];
for (let page = 1; page <= 604; page += 1) {
  pageStartIndex[page] = pageStartIndex[page - 1] + (geometry[page]?.markers.length ?? 0);
}

export function getPageViewBox(page: number): { width: number; height: number } | null {
  const g = geometry[page];
  return g ? { width: g.vb[0], height: g.vb[1] } : null;
}

/** Page-local position of an ayah: the Nth ayah that ends (or continues) on this page. */
export type PageAyahSlot = { page: number; slot: number; globalIndex: number };

/**
 * Maps a point in SVG coordinates to the ayah drawn there. Text reads right-to-left,
 * top-to-bottom, and each ayah ends with a marker, so the tapped ayah is the one whose
 * end marker is the first at-or-after the tap in reading order. Past the last marker the
 * ayah continues onto the next page. Returns null for taps away from any line of text.
 */
export function locateAyah(page: number, x: number, y: number): PageAyahSlot | null {
  const g = geometry[page];
  if (!g || g.lines.length === 0) return null;

  let line = 0;
  for (let i = 1; i < g.lines.length; i += 1) {
    if (Math.abs(g.lines[i] - y) < Math.abs(g.lines[line] - y)) line = i;
  }
  const pitch = g.lines.length > 1 ? (g.lines[g.lines.length - 1] - g.lines[0]) / (g.lines.length - 1) : 27;
  if (Math.abs(g.lines[line] - y) > pitch * 0.6) return null;
  if (x < g.x[0] - 6 || x > g.x[1] + 6) return null;

  let slot = g.markers.length;
  for (let i = 0; i < g.markers.length; i += 1) {
    const [mLine, mX] = g.markers[i];
    if (mLine > line || (mLine === line && mX <= x + 4)) {
      slot = i;
      break;
    }
  }
  return { page, slot, globalIndex: pageStartIndex[page - 1] + slot };
}

export type HighlightRect = { x: number; y: number; width: number; height: number };

/** Rectangles (SVG coordinates) covering the ayah in the given slot of a page. */
export function highlightRects(page: number, slot: number): HighlightRect[] {
  const g = geometry[page];
  if (!g || g.lines.length === 0) return [];
  const pitch = g.lines.length > 1 ? (g.lines[g.lines.length - 1] - g.lines[0]) / (g.lines.length - 1) : 27;
  const [minX, maxX] = g.x;
  const lastLine = g.lines.length - 1;

  // Text starts at the right edge: just left of the previous marker, or page top.
  const prev = slot > 0 ? g.markers[slot - 1] : null;
  const next = slot < g.markers.length ? g.markers[slot] : null;
  const startLine = prev ? prev[0] : 0;
  const startX = prev ? prev[1] - 7 : maxX;
  const endLine = next ? next[0] : lastLine;
  const endX = next ? next[1] - 7 : minX;

  const rects: HighlightRect[] = [];
  for (let line = startLine; line <= endLine; line += 1) {
    const right = line === startLine ? startX : maxX;
    const left = line === endLine ? endX : minX;
    if (right - left < 2) continue;
    rects.push({ x: left, y: g.lines[line] - pitch * 0.48, width: right - left, height: pitch * 0.96 });
  }
  return rects;
}
